style.css:
@-moz-document domain("discord.com") {
:root {
        --gradient-bg: linear-gradient(135deg, #ff416c, #ff4b2b);
        --gradient-text: linear-gradient(45deg, #ffcc00, #ff6699);
        --discord-dark: #2c2f33;
        --discord-darker: #23272a;
        --discord-light: #99aab5;
    }

    body {
        background: var(--gradient-bg) !important;
    }

    .appMount-3lHmkl,
    .bg-1QIAus {
        background: var(--discord-darker) !important;
    }

    .theme-dark .title-3qD0b- {
        background: var(--gradient-text);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    .sidebar-1tnWFu {
        background: var(--discord-dark) !important;
    }

    .chatContent-3KubbW {
        background: rgba(0, 0, 0, 0.6) !important;
    }

    .message-2qnXI6 {
        background: rgba(0, 0, 0, 0.3) !important;
        border-radius: 8px;
        padding: 5px;
    }
}
